def subterms(x):
    out=[]
    todo=[x]
    while todo:
        value=todo.pop()
        if isinstance(value,list) and value:
            out.append(value)
            i=1
            while i<len(value):
                if isinstance(value[i],list):
                    todo.append(value[i])
                i+=1
    return out

def has_tag(x,name):
    for value in subterms(x):
        if value[0]==name:
            return True
    return False

def owner_ok(x):
    return isinstance(x,list) and bool(x) and x[0] in ('receiving_party','party','named_recipient')

def class_tags(x,definitions):
    tags=set()
    todo=[x]
    seen=set()
    while todo:
        value=todo.pop()
        if not isinstance(value,list) or not value:
            continue
        name=value[0]
        if name=='representatives_of':
            key=str(value[1]) if len(value)>1 else ''
            if key not in seen:
                seen.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
            continue
        if name=='internal_personnel_of' and len(value)>1 and owner_ok(value[1]):
            tags.add('employees_of')
        if name in ('employees_of','directors_of','officers_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','consultants_of','agents_of','independent_contractors_of','lenders_of'):
            if len(value)>1 and owner_ok(value[1]):
                tags.add(name)
            continue
        if name=='third_parties':
            tags.add(name)
            continue
        i=1
        while i<len(value):
            if isinstance(value[i],list):
                todo.append(value[i])
            i+=1
    return tags

def unique(xs):
    out=[]
    for x in xs:
        if x not in out:
            out.append(x)
    return out

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=collect_entries(premises)
    if task in ('nda-5','nda-7'):
        return disclosure_decision(task,entries)
    disposal=[]
    retention_yes=[]
    retention_no=[]
    no_disposal=[]
    no_retention=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_yes.append(root)
        elif term[0]=='retention_prohibition':
            retention_no.append(root)
        elif term[0]=='complete_source_no_disposal_obligation':
            no_disposal.append(root)
        elif term[0]=='complete_source_no_retention_effect':
            no_retention.append(root)
    if task=='nda-16':
        agreement=[]
        relevant=[]
        for term,root in disposal:
            action=term[2]
            trigger=term[3]
            if has_tag(action,'return_to') or has_tag(action,'destroy'):
                relevant.append(root)
                if has_tag(trigger,'agreement_termination'):
                    agreement.append(root)
        if agreement:
            return {'handled':True,'answer':'Entailment','used_nodes':unique(agreement)}
        if relevant or no_disposal:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+no_disposal)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_yes:
        return {'handled':True,'answer':'Entailment','used_nodes':unique(retention_yes)}
    if retention_no:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(retention_no)}
    disposal_roots=[]
    for term,root in disposal:
        if has_tag(term[2],'return_to') or has_tag(term[2],'destroy'):
            disposal_roots.append(root)
    if disposal_roots or no_retention or no_disposal:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(disposal_roots+no_retention+no_disposal)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def disclosure_decision(task,entries):
    definitions=[]
    definition_roots=[]
    permissions=[]
    prohibitions=[]
    relevant=[]
    absence=[]
    for term,root in entries:
        if term[0]=='complete_source_no_disclosure_permission':
            absence.append(root)
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose':
            continue
        if not has_tag(action[1],'confidential_information'):
            continue
        relevant.append(root)
        tags=class_tags(action[2],definitions)
        if term[0]=='permission':
            permissions.append((root,tags,action[2]))
        else:
            prohibitions.append((root,tags,action[2]))
    wanted={'employees_of'} if task=='nda-5' else {'third_parties','consultants_of','agents_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','independent_contractors_of'}
    for root,tags,recipient in permissions:
        if tags.intersection(wanted):
            used=[root]
            if has_tag(recipient,'representatives_of'):
                used.extend(definition_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
    for root,tags,recipient in prohibitions:
        if has_tag(recipient,'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+definition_roots+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def collect_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for node in nodes:
        byid[node.get('id')]=node
    entries=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            node_id=todo.pop()
            if node_id in seen or node_id not in byid:
                continue
            seen.add(node_id)
            node=byid[node_id]
            for term in subterms(node.get('term')):
                entries.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return entries
